def solve(nums, k):
    def solve_helper(nums, k):
        def copy(nums, new_nums):
            if nums == [] and new_nums == []:
                return []
            elif nums == []:
                return new_nums
            elif new_nums == []:
                return nums
            else:
                return [nums[0]] + copy(nums[1:], new_nums)

        def merge(a, b):
            if not a:
                return b
            if not b:
                return a
            if a[0] < b[0]:
                return [a[0]] + merge(a[1:], b)
            else:
                return [b[0]] + merge(a, b[1:])

        def kth_smallest(nums, k):
            if len(nums) == 1:
                return nums[0]
            mid = len(nums) // 2
            left = nums[:mid]
            right = nums[mid:]
            left_sorted = kth_smallest(left, k)
            right_sorted = kth_smallest(right, k)
            if left_sorted < right_sorted:
                return left_sorted
            else:
                return right_sorted

        if k == 1:
            return min(nums)
        elif k == len(nums):
            return max(nums)
        else:
            return kth_smallest(nums, k)

    return solve_helper(nums, k)

