def solve(n, edges):
    def dfs(node, visited):
        for neighbor in range(n):
            if neighbor != node:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    dfs(neighbor, visited)

    visited = [False] * n
    count = 0
    for i in range(n):
        if not visited[i]:
            visited[i] = True
            dfs(i, visited)
            count += 1
    return count

