    parent = list(range(n))

    def find(x):
        while x != parent[x]:
            x = parent[x]
        return x

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            parent[root_y] = root_x

    for u, v in edges:
        union(u, v)

    # Count unique roots
    roots = set()
    for i in range(n):
        roots.add(find(i))

    return len(roots)

def solve(n, edges):
    def dfs(u, v):
        if u == v:
            return
        if u not in parents and v not in parents:
            parents[u] = v
            parents[v] = u
            dfs(u, v)
    parents = {}
    for u, v in edges:
        parents[u] = v
        parents[v] = u
    components = 0
    visited = set()
    for i in range(n):
        if i not in visited:
            components += 1
            stack = [i]
            visited.add(i)
            while stack:
                node = stack.pop()
                for neighbor in [parents.get(node, None), parents.get(node, None)]:
                    if neighbor is not None and neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
    return components

def solve(n, edges):
    def dfs(node, visited, adj):
        for neighbor in adj[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(neighbor, visited, adj)

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    components = 0

    for node in range(n):
        if node not in visited:
            components += 1
            dfs(node, visited, adj)

    return components

def solve(n, edges):
    def dfs(node, visited):
        visited.add(node)
        for neighbor in edges[node][1] if len(edges[node]) > 1 else []:
            if neighbor not in visited:
                dfs(neighbor, visited)

    visited = set()
    components = 0

    for node in range(n):
        if node not in visited:
            dfs(node, visited)
            components += 1

    return components

def solve(n, edges):
    parent = [i for i in range(n)]
    for u, v in edges:
        parent[root(u, parent)] = root(v, parent)

    components = set()
    for i in range(n):
        components.add(root(i, parent))

    return len(components)

def root(u, parent):
    while parent[u] != u:
        parent[u] = parent[parent[u]]
        u = parent[u]
    return u

